const BOX = { cx: 112, cy: 154, scale: 40 };
const objX = (x: number) => f(BOX.cx + BOX.scale * x);
const objY = (y: number) => f(BOX.cy - BOX.scale * y);

/** Fingertip drawing, in stage units outward along the finger from the contact. */
