/** Pointer reach around a fingertip, so a finger is easy to grab on a phone. */
const GRAB_R = 16;

/** The test pushes: arrows on a ring, pointing at the box centre. */
const PUSH_TIP = 86;
const PUSH_TAIL = 106;
const HEAD_LEN = 7;
const HEAD_HALF = 4.5;

/** The fan drawn for each friction cone, in object units. */
const FAN_LEN = 0.5;
