                { label: 'goal', value: goal.label },
                { label: 'steps', value: String(steps) },
                { label: 'distance', value: formatDistance(distance) },
              ]}
            />
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <InstrumentFigure
      figureId="jepa-planning"
      className={className}
      heading="Replanning toward a goal latent"
      controls={controls}
