  defaultCandidates?: number;
  className?: string;
};

type GoalId = 'pick' | 'place';

const W = CHART_VIEW_WIDTH;
const BUDGET_STEP = 4;
/** Planning steps already taken when the figure opens, after a reset and after a goal change. */
