    let last = 0;
    const loop = (now: number) => {
      const dt = last ? Math.min((now - last) / 1000, LONGEST_FRAME) : 1 / 60;
      last = now;
      const moving = stepMotion(from, target, pass, dt);
      drawPose(parts, from);
