    setRun((prev) => ({ ...prev, sim: applyPush(prev.sim) }));
    if (!playing) setPlaying(true);
  };

  const reset = () => {
    setPlaying(false);
    setGains({ ...DEFAULT_GAINS, kp: defaultKp });
    setRun({ sim: INITIAL_STATE, history: [INITIAL_STATE] });
