/** One plan's cycle on the reader, in seconds on screen: feed, act, cut, push, drop into the bin. */
export function cycleOf(ta: number, plans: number) {
  const overhead = Math.min(1, 9 / Math.max(1, plans));
  return {
    feed: 0.8 * overhead,
    act: (ta / CONTROL_HZ) * SLOW,
    cut: 0.4 * overhead,
    push: 0.6 * overhead,
    drop: 0.6 * overhead,
