        <circle
          key={i}
          cx={f(OUT_X + BEAD_R + i * BEAD_PITCH)}
          cy={ROW.summary.mid}
          r={BEAD_R}
          fill={STATE}
          fillOpacity={level}
          stroke={STATE}
          strokeWidth={CHART_STROKE.structure}
        />
      ))}
    </g>
  );
}

/** Plain facts: the next moment written as a statement about the objects. */
function FactTag({ marked }: { marked: boolean }) {
