function ogTargetsFor(id: string): TestTarget[] {
  const targets = OG_ROW_TARGETS[id];
  if (!targets) {
    throw new Error(`${id} is an Open Graph row with no test that plants a defect in it`);
  }
  return [OG_EVIDENCE_GREEN_TARGET, OG_MANIFEST_READER_TARGET, ...targets];
}

function testTargetsFor(id: string): TestTarget[] {
  if (OG_ASSERTIONS.has(id)) return ogTargetsFor(id);
  if (CONTROL_STATE_ASSERTION_IDS.has(id)) {
    return controlStateTargetsFor(id as ControlStateAssertion);
  }

  return [SEARCH_SWEEP_TARGET, SEARCH_READER_TARGET];
}
if (MAP_ASSERTIONS.has(id)) {
  return [MAP_SWEEP_TARGET, MAP_READER_TARGET];
}
if (INTERACTIVE_CAPTURE_ASSERTIONS.has(id)) {
  return [
    CENSUS_INTERACTIVE_TARGET,
    INTERACTIVE_STATE_TARGET,
    INTERACTIVE_CAPTURE_SWEEP_TARGET,
    INTERACTIVE_CAPTURE_SHEET_TARGET,
    INTERACTIVE_CAPTURE_VERDICT_TARGET,
    INTERACTIVE_CAPTURE_PLANT_TARGET,
    INTERACTIVE_CAPTURE_READER_TARGET,
  ];
}
if (LEDGER_ASSERTION_IDS.has(id)) {
  return [
    CENSUS_INTERACTIVE_TARGET,
    INTERACTIVE_STATE_TARGET,
    LEDGER_VERDICT_TARGET,
    LEDGER_PLANT_TARGET,
    LEDGER_READER_TARGET,
    // The legend sweep's own series reading still decides the default and
    // pressed states the ledger re-reads at every slider end.
    ...(INTERACTIVE_DATA_TARGETS[id] ? [INTERACTIVE_DATA_TARGETS[id]] : []),
  ];
}

  return [HOME_TOOLS_SWEEP_TARGET, HOME_TOOLS_READER_TARGET];
}
if (GLOBAL_CONVERGENCE_ASSERTIONS.has(id)) {
  return [
    GLOBAL_CONVERGENCE_SWEEP_TARGET,
    GLOBAL_CONVERGENCE_PLANT_TARGET,
    GLOBAL_CONVERGENCE_READER_TARGET,
    GLOBAL_CONVERGENCE_VERDICT_TARGET,
  ];
}

