      const pointStage = pointCurvePoints().map((p) => [x(p.mu), y(p.success)] as [number, number]);
      const dense = [curve(pointSuccess), curve((mu) => drSuccess(mu, range))];
      for (let m = 20; m <= 150; m++) {
