      expect(edges.filter(x => kolBatch20261021Appends.includes(x.id)).map(x => x.id))
        .toEqual(blocks.map(b => `kol-batch-20261021-${b.domain}-citation-rendering`));
      // The 2026-10-24 KOL overdue triage and the 2026-10-25 KOL queue
